window.SECTIONS = {"arjinin": "<div id=\"arjinin\" class=\"section\">\n  <h3>Arjinin (L-Arjinin)</h3>\n\n  <input type=\"number\" id=\"a_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaArjinin()\" />\n  <span id=\"a_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaArjinin()\">Hesapla</button>\n  <div id=\"arjininSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <!-- Bilgilendirme -->\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">Arjinin Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Nitrik oksit (NO) üretimini destekleyerek damarları genişletir, kan akışını ve “pump” etkisini artırır; dayanıklılığa katkı sağlayabilir.<br>\n        <strong>Nasıl kullanılır:</strong> Önerilen miktar, antrenmandan 30–60 dakika önce 3–6 gram alınmasıdır.<br>\n        <strong>Etki tipi ve süresi nedir:</strong> <span class=\"akut-vurgu\">Etkisi akuttur.</span> 30–60 dakika içinde hissedilebilir.\n      </div>\n    </div>\n\n  <!-- SSS -->\n<div class=\"faq-section\">\n  <h5 class=\"faq-header\">Sıkça Sorulan Sorular:</h5>\n  <div class=\"accordion-container\">\n\n    <!-- 1. Sağlığa zararlı mı? -->\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Arjinin sağlığa zararlı mı?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul>\n            <li>Önerilen dozlarda genel olarak güvenlidir.</li>\n            <li>Yüksek dozlarda mide rahatsızlığı, bulantı, ishal görülebilir.</li>\n            <li>Tansiyonu düşük olanlar ve tansiyon ilacı kullananlar dikkatli olmalıdır.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <!-- 2. Sitrülin ile farkı nedir? -->\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Sitrülin ile farkı nedir?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul>\n            <li>Sitrülin, vücutta arjinine dönüştüğü için plazma arjinin seviyelerini yükseltmede genellikle daha etkilidir.</li>\n            <li>Ağızdan alınan arjinin, sindirim sistemi ve karaciğerde büyük oranda parçalanır (first-pass etkisi), bu nedenle hedefe ulaşan miktar sınırlıdır.</li>\n            <li>Çalışmalar, sporcularda pump ve performans artışı için 6–8 g sitrülin malatın 3–6 g arjinine kıyasla daha tutarlı sonuç verdiğini göstermektedir.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <!-- 3. Neden bazı sporcular arjinin yerine sitrülin tercih eder? -->\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Neden bazı sporcular arjinin yerine sitrülin tercih eder?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul>\n            <li>Sitrülin, sindirimde parçalanmadan kana karışır ve arjinin seviyelerini yükseltir.</li>\n            <li>Daha uzun süreli nitrik oksit desteği sağlar, “pump” etkisi antrenman boyunca korunabilir.</li>\n            <li>Mide hassasiyeti yaşayan sporcular sitrülin ile genelde daha iyi tolere eder.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <!-- 4. Mide rahatsızlığı normal mi? -->\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Mide rahatsızlığı normal mi?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul>\n            <li>Evet, özellikle yüksek dozlarda şişkinlik, bulantı veya ishal görülebilir.</li>\n            <li>Dozu azaltmak, gün içine bölmek veya hafif bir öğünle almak toleransı artırabilir.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</div>\n\n    <!-- Doz Bilgisi -->\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Mide rahatsızlığı, bulantı, gevşek dışkılama/ishal.</li>\n            <li>Duyarlı kişilerde hafif tansiyon düşüşü ve baş dönmesi.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Daha belirgin “pump” hissi.</li>\n            <li>Kan akışında ve egzersiz sırasında hissedilen dayanıklılıkta artış.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek ve Uzun Süreli Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 20 gram üzeri ve uzun süreli kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Şiddetli mide-bağırsak rahatsızlığı (kramp, kusma, ishal).</li>\n                <li>Belirgin tansiyon düşüşü; baş dönmesi, bayılma riski.</li>\n                <li>Elektrolit ve sıvı dengesizliği.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n\n  <!-- Uyarı -->\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>", "bcaa": "<div id=\"bcaa\" class=\"section\">\n  <h3>BCAA</h3>\n  <input type=\"number\" id=\"bcaa_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaBcaa()\" />\n  <span id=\"bcaa_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaBcaa()\">Hesapla</button>\n  <div id=\"bcaaSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <!-- Bilgilendirme -->\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">BCAA Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Protein eksikliği durumunda kas yıkımını azaltmaya ve toparlanmayı desteklemeye yardımcı olabilir.<br>\n        <strong>Nasıl kullanılır:</strong> Önerilen doz antrenman öncesi/sonrası 5-10 gram arasıdır.<br>\n        <strong>Etki tipi ve süresi nedir:</strong> <span class=\"akut-vurgu\">Etkisi akuttur.</span> Akut toparlanma ve kas ağrısı azalmasında hızlı etki gösterebilir.\n      </div>\n    </div>\n\n    <!-- Sıkça Sorulan Sorular -->\n    <div class=\"faq-section\">\n      <h5 class=\"faq-header\">Sıkça Sorulan Sorular:</h5>\n      <div class=\"accordion-container\">\n\n        <!-- 1. Sağlığa Zararlı mı -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">BCAA sağlığa zararlı mı?</button>\n          <div class=\"accordion-content\">\n            <ul>\n              <li>Önerilen dozlarda (5–10 g/gün) sağlıklı bireyler için genellikle güvenlidir.</li>\n              <li>Uzun süreli yüksek dozlar (>15 g/gün) insülin direnci riskini artırabilir.</li>\n              <li>Karaciğer ve böbrek sorunları olan bireylerde ek yük oluşturabileceği için tıbbi kontrol gerekebilir.</li>\n            </ul>\n          </div>\n        </div>\n\n        <!-- 2. Gerekli mi, Kullanmalı mıyım -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">BCAA supplementi gerçekten gerekli mi, kullanmalı mıyım?</button>\n          <div class=\"accordion-content\">\n            <ul>\n              <li>Yeterli miktarda protein (≥1.6 g/kg/gün) alıyorsan BCAA takviyesine gerek yoktur.</li>\n              <li>Whey protein gibi tam kaynaklar hem BCAA hem diğer amino asitleri içerdiği için çok daha etkilidir.</li>\n              <li>BCAA, kas yapımını değil, sadece yıkımı azaltabilir — bu yüzden etkisi sınırlıdır.</li>\n              <li>Açlıkta antrenman gibi bazı spesifik durumlarda destekleyici olabilir ama bu bile tam proteinle daha iyi yönetilebilir.</li>\n            </ul>\n          </div>\n        </div>\n\n        <!-- 3. 4:1:1 - 2:1:1 Farkı -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">4:1:1 ve 2:1:1 oranları arasındaki fark nedir?</button>\n          <div class=\"accordion-content\">\n            <ul>\n              <li>Her iki oran da lösin:izolösin:valin oranlarını temsil eder.</li>\n              <li>4:1:1 oranı lösin miktarını artırarak mTOR(kas büyüme sinyali) aktivasyonunu hedefler.</li>\n              <li>2:1:1 oranı ise doğal protein kaynaklarına daha yakındır ve daha dengelidir.</li>\n              <li>Araştırmalar lösin dozunun bir noktadan sonra ek etki yaratmadığını, 2:1:1’in yeterli olduğunu gösteriyor.</li>\n            </ul>\n          </div>\n        </div>\n\n        <!-- 4. BCAA vs EAA -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">BCAA ile EAA arasındaki fark nedir?</button>\n          <div class=\"accordion-content\">\n            <ul>\n              <li>BCAA sadece 3 amino asit içerir: lösin, izolösin, valin.</li>\n              <li>EAA ise vücudun sentezleyemediği 9 temel amino asidi içerir.</li>\n              <li>EAA direkt olarak kas protein sentezini desteklerken, BCAA sadece kas yıkımını azaltır.</li>\n              <li>EAA, hem anabolik etki hem toparlanma açısından BCAA’dan daha üstün ve kapsamlıdır.</li>\n            </ul>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <!-- Doz Bilgisi -->\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Sindirim sorunları (şişkinlik, gaz) görülebilir.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Yoğun antrenman sonrası ek toparlanma desteği.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 30 gram üzeri kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Böbrekler ve karaciğer üzerinde artan potansiyel yük.</li>\n                <li>Diğer amino asitlerin emilimini engelleyerek dengesizliğe yol açabilir.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n\n  <!-- Uyarı -->\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>", "beta": "<div id=\"beta\" class=\"section\">\n  <h3>Beta-Alanin</h3>\n\n  <input type=\"number\" id=\"b_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaBeta()\" />\n  <span id=\"b_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaBeta()\">Hesapla</button>\n  <div id=\"betaSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <!-- Bilgilendirme (Sadeleştirilmiş) -->\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">Beta-Alanin Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Laktik asiti tamponlayarak egzersiz yorgunluğunu geciktirir ve performansı artırır.<br>\n        <strong>Nasıl kullanılır:</strong> Genelde günün herhangi bir saatinde 3–6 gram arası alarak kullanılır.<br>\n        <strong>Etki tipi ve süresi nedir:</strong> <span class=\"birikimli-vurgu\">Etkisi birikimlidir.</span> 3–4 hafta içinde hissedilmeye başlar.\n      </div>\n    </div>\n\n    <!-- SSS -->\n    <div class=\"faq-section\">\n      <h5 class=\"faq-header\">Sıkça Sorulan Sorular:</h5>\n      <div class=\"accordion-container\">\n\n        <!-- 1. Sağlığa zararlı mı? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Beta-alanin sağlığa zararlı mı?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Genellikle günlük önerilen dozda (3–6 g) kısa ve uzun vadede herhangi bir zarar vermez.</li>\n                <li>Yüksek dozlarda mide rahatsızlığı veya ishal görülebilir.</li>\n                <li>Böbrek veya karaciğer sorunu olanlar için doktor kontrolü önerilir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. Karıncalanma hissi normal mi? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Karıncalanma hissi (parestezi) normal mi?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Beta-alanin alımından sonra ciltte karıncalanma sık görülen ve zararsız bir etkidir.</li>\n                <li>Bu his, ürünün etkisinin başladığı anlamına gelmez.</li>\n                <li>Dozu gün içine yaymak veya yemekle birlikte almak bu hissi azaltabilir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. Kas karnozini nedir, depolanma süreci nasıldır? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Kas karnozini nedir, depolanma süreci nasıldır?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Karnozin, kaslarda laktik asidi tamponlayarak yorgunluğu azaltan bir proteindir.</li>\n                <li>Beta-alanin kullanımıyla karnozin seviyesi 3–4 hafta içinde yükselmeye başlar.</li>\n                <li>6–8 haftada %40–60 artış, 10–12 haftada %80’e kadar dolum gerçekleşir.</li>\n                <li>Kullanım bırakıldığında 4–6 hafta içinde düşmeye başlar, 8–12 haftada başlangıç seviyesine döner.</li>\n                <li>Dinlenme günlerinde de alınması, karnozin seviyesinin korunması için önemlidir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <!-- Doz Bilgisi -->\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Parestezi (ciltte zararsız karıncalanma hissi) şiddetlenebilir.</li>\n            <li>Nadir durumlarda mide rahatsızlığı veya ishal.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Kas karnozin depolarının daha hızlı dolması potansiyeli.</li>\n            <li>Bazı kullanıcılar için parestezi hissi motivasyon kaynağı olabilir.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek ve Uzun Süreli Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 10 gram üzeri ve uzun süreli kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Şiddetli ve rahatsız edici parestezi.</li>\n                <li>Ciddi mide rahatsızlığı, mide krampı, ishal.</li>\n                <li>Çok nadiren, diğer organlar üzerinde potansiyel olumsuz etkiler.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n\n  <!-- Uyarı -->\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>", "eaa": "<div id=\"eaa\" class=\"section\">\n  <h3>EAA (Esansiyel Amino Asitler)</h3>\n\n  <input type=\"number\" id=\"eaa_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaEaa()\" />\n  <span id=\"eaa_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaEaa()\">Hesapla</button>\n  <div id=\"eaaSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <!-- Bilgilendirme (Sadeleştirilmiş) -->\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">EAA Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Protein alımı yetersiz olduğunda kas protein sentezini desteklemeye yardımcı olur.<br>\n        <strong>Nasıl kullanılır:</strong> Önerilen doz antrenman öncesi/sonrası 10-20 gram arasıdır.<br>\n        <strong>Etki tipi ve süresi nedir:</strong> <span class=\"karma-vurgu\">Etkisi hem kısa hem \"uzun\" vadelidir.</span> 2–4 hafta içinde toparlanmada fark hissedilebilir.\n      </div>\n    </div>\n\n    <!-- SSS -->\n    <div class=\"faq-section\">\n      <h5 class=\"faq-header\">Sıkça Sorulan Sorular:</h5>\n      <div class=\"accordion-container\">\n\n        <!-- 1. EAA sağlığa zararlı mı? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">EAA sağlığa zararlı mı?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Genel kullanım dozlarında (günlük 10–30 g) sağlıklı bireyler için güvenlidir.</li>\n                <li>Günlük 40 g üzeri alım böbreklerde ekstra yük oluşturabilir.</li>\n                <li>Amino asit dengesizliği riski nedeniyle yüksek lösin oranlı(%35) ürünlerden kaçınılmalıdır.</li>\n                <li>Böbrek sorunu olan bireyler mutlaka doktor kontrolünde kullanmalıdır.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. EAA gerçekten gerekli mi? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">EAA supplementi gerçekten gerekli mi?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Günlük 1.6–2.2 g/kg protein alıyorsan EAA’ya ihtiyaç yoktur.</li>\n                <li>Whey gibi tam protein kaynakları zaten tüm esansiyel amino asitleri içerir.</li>\n                <li>EAA, eksik protein alımında destek olabilir ama tam kaynakların yerini tutmaz.</li>\n                <li>Yetersiz beslenen bireyler veya açlıkta antrenman yapanlar için sınırlı fayda sağlayabilir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. EAA ile BCAA arasındaki fark nedir? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">EAA ile BCAA arasındaki fark nedir?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>BCAA sadece 3 amino asit içerir: lösin, izolösin, valin.</li>\n                <li>EAA ise vücudun sentezleyemediği 9 temel amino asidi içerir.</li>\n                <li>EAA, doğrudan kas protein sentezini tetiklerken BCAA sadece yıkımı azaltabilir.</li>\n                <li>Bu nedenle EAA, BCAA’ya göre daha kapsamlı ve etkili bir formüldür.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <!-- Doz Bilgisi -->\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Hafif mide rahatsızlığı.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Yoğun antrenman sonrası toparlanma desteği.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 40 gram üzeri kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Böbreklerde ekstra yük.</li>\n                <li>Amino asit dengesizliği.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n\n  <!-- Uyarı -->\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>", "glutamin": "<div id=\"glutamin\" class=\"section\">\n  <h3>Glutamin</h3>\n\n  <input\n    type=\"number\"\n    id=\"glutamin_kilo\"\n    placeholder=\"Kilonuz (kg)\"\n    onkeyup=\"if(event.keyCode === 13) hesaplaGlutamin()\"\n  />\n  <span id=\"glutamin_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaGlutamin()\">Hesapla</button>\n  <div id=\"glutaminSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <!-- Bilgilendirme (Sadeleştirilmiş) -->\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">Glutamin Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Bağırsak sağlığını destekler, yorgunluk hissine etkisi minimal.<br>\n        <strong>Nasıl kullanılır:</strong> Spor sonrası veya yatmadan önce 5-10 gram alınır.<br>\n        <strong>Etki tipi ve süresi nedir:</strong> <span class=\"uzun-vade-vurgu\">Etkisi uzun vadelidir.</span> Bağırsak semptomları ve toparlanma birkaç gün, spor performansında etkisi ise çok sınırlıdır.\n      </div>\n    </div>\n\n    <!-- SSS -->\n    <div class=\"faq-section\">\n  <h5 class=\"faq-header\">Sıkça Sorulan Sorular:</h5>\n  <div class=\"accordion-container\">\n\n    <!-- 1. Glutamin sağlığa zararlı mı? -->\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Glutamin sağlığa zararlı mı?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul class=\"not-maddeler\">\n            <li>Günlük 20 g altı kullanım genellikle güvenlidir.</li>\n            <li>20 g ve üzeri uzun süre alınırsa böbrek yükü ve sindirim sorunları riski artar.</li>\n            <li>Böbrek veya karaciğer problemi olanlar doktor onayı almalı.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <!-- 2. Glutamin gerçekten gerekli mi, kimler kullanmalı? -->\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Glutamin gerçekten gerekli mi, kimler kullanmalı?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul class=\"not-maddeler\">\n            <li>Yeterli protein alıyorsan ekstra glutamine ihtiyaç yok.</li>\n            <li>Sağlıklı bireylerde kas gelişimine katkısı kanıtlanmamış.</li>\n            <li>Whey proteini ve diğer tam protein kaynakları zaten yeterli glutamin içerir.</li>\n            <li>Ancak şu gruplarda sınırlı fayda sağlayabilir:\n              <ul>\n                <li>Kronik bağırsak sorunu yaşayanlar (IBS, sızdıran bağırsak).</li>\n                <li>Aşırı yoğun antrenman yapan elit sporcular (günde 2+ saat).</li>\n                <li>Vegan veya yetersiz protein tüketen bireyler.</li>\n              </ul>\n            </li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <!-- 3. Bağırsak sağlığı için faydalı mı? -->\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Bağırsak sağlığı için faydalı mı?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul class=\"not-maddeler\">\n            <li>IBS veya sızdıran bağırsak sendromu gibi durumlarda destek olabilir.</li>\n            <li>Genel popülasyonda etkisi sınırlı ve kanıt düzeyi düşüktür.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</div>\n\n    <!-- Doz Bilgisi -->\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Hafif mide rahatsızlığı ve gaz.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Yoğun antrenman sonrası bağışıklık desteği.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 40 gram üzeri kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Böbreklerde ekstra yük.</li>\n                <li>Şiddetli sindirim problemleri.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n\n  <!-- Uyarı -->\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya\n    supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>", "hepsi": "<div id=\"hepsi\" class=\"section\">\n  <h3>Toplu Supplement Hesaplama</h3>\n\n  <div class=\"accordion-container calculator-accordion\">\n    <div class=\"accordion-item\">\n      <button type=\"button\" class=\"accordion-header\">Toplu supplement hesaplamayı aç</button>\n      <div class=\"accordion-content\">\n\n        <!-- Supplement seçimleri -->\n        <div class=\"checkbox-group\">\n          <label for=\"chk_protein\"><input type=\"checkbox\" id=\"chk_protein\" /> Protein</label>\n          <label for=\"chk_kreatin\"><input type=\"checkbox\" id=\"chk_kreatin\" /> Kreatin</label>\n          <label for=\"chk_beta\"><input type=\"checkbox\" id=\"chk_beta\" /> Beta-Alanin</label>\n          <label for=\"chk_sitrulin\"><input type=\"checkbox\" id=\"chk_sitrulin\" /> Sitrülin Malat</label>\n          <label for=\"chk_karnitin\"><input type=\"checkbox\" id=\"chk_karnitin\" /> L-Karnitin</label>\n          <label for=\"chk_kafein\"><input type=\"checkbox\" id=\"chk_kafein\" /> Kafein</label>\n          <label for=\"chk_bcaa\"><input type=\"checkbox\" id=\"chk_bcaa\" /> BCAA</label>\n          <label for=\"chk_glutamin\"><input type=\"checkbox\" id=\"chk_glutamin\" /> Glutamin</label>\n          <label for=\"chk_arjinin\"><input type=\"checkbox\" id=\"chk_arjinin\" /> Arjinin</label>\n          <label for=\"chk_eaa\"><input type=\"checkbox\" id=\"chk_eaa\" /> EAA</label>\n        </div>\n\n        <!-- Kilo girişi -->\n        <input type=\"number\" id=\"toplu_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaToplu()\" />\n        <span id=\"toplu_kilo_warning\" class=\"input-warning\"></span>\n\n        <!-- Hedef seçimi -->\n        <div class=\"accordion-container calculator-accordion hedef-accordion\" data-hedef-target=\"toplu_hedef\">\n          <div class=\"accordion-item\">\n            <button type=\"button\" class=\"accordion-header\">Hedefini seç</button>\n            <div class=\"accordion-content\">\n              <div class=\"hedef-options\">\n                <button type=\"button\" class=\"hedef-option\" data-value=\"koruma\">Kilo Korumak</button>\n                <button type=\"button\" class=\"hedef-option\" data-value=\"alma\">Kilo Almak</button>\n                <button type=\"button\" class=\"hedef-option\" data-value=\"verme\">Kilo Vermek</button>\n              </div>\n              <select id=\"toplu_hedef\" class=\"hedef-select-hidden\">\n                <option value=\"\">-- Hedefinizi Seçiniz --</option>\n                <option value=\"koruma\">Kilo Korumak</option>\n                <option value=\"alma\">Kilo Almak</option>\n                <option value=\"verme\">Kilo Vermek</option>\n              </select>\n              <span id=\"toplu_hedef_warning\" class=\"input-warning\"></span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Hesaplama butonu -->\n        <button onclick=\"hesaplaToplu()\">Hesapla</button>\n\n        <!-- Sonuç alanı -->\n        <div id=\"topluSonuc\" class=\"result\"></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Uyarı -->\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. \n    Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>\n", "kafein": "<div id=\"kafein\" class=\"section\">\n  <h3>Kafein</h3>\n\n  <input type=\"number\" id=\"c_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaKafein()\" />\n  <span id=\"c_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaKafein()\">Hesapla</button>\n  <div id=\"kafeinSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">Kafein Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Merkezi sinir sistemini uyararak uyanıklığı artırır, yorgunluğu azaltır, odaklanmayı güçlendirir ve egzersiz performansını (özellikle dayanıklılık ve güç) artırır.\n        <br><strong>Nasıl kullanılır:</strong> Önerilen doz, antrenmandan 30-60 dakika önce alınır. Kafein toleransı kişiden kişiye değiştiği için düşük dozla başlayıp kademeli artırmak önemlidir.\n        <br><strong>Etki tipi ve süresi nedir:</strong> <span class=\"akut-vurgu\">Etkisi akuttur.</span> Alımdan sonra 30-60 dakika içinde etkileri başlar.\n\n      </div>\n    </div>\n\n    <div class=\"faq-section\">\n  <h5 class=\"info-header\">Sıkça Sorulan Sorular:</h5>\n  <div class=\"accordion-container\">\n\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Kafein sağlığa zararlı mı?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul class=\"not-maddeler\">\n            <li>Yüksek dozda tansiyonu yükseltebilir, kalp ritmini bozabilir.</li>\n            <li>Düzenli ve yüksek dozda alım bağımlılık yapabilir. Bırakıldığında baş ağrısı, yorgunluk gibi belirtiler görülebilir.</li>\n            <li>Hafif idrar söktürücü etkisi olsa da vücut buna uyum sağlar; yeterli su tüketiliyorsa dehidrasyon riski düşüktür.</li>\n            <li>1 gram üzeri dozlar ciddi yan etkilere neden olabilir; 5 gram ve üzeri hayati tehlike oluşturur.</li>\n            <li>Kalp-damar hastalığı, yüksek tansiyon, anksiyete bozukluğu veya uyku problemi olan bireylerde dikkatli kullanılmalıdır.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Kafein toleransı nedir, nasıl sıfırlanır?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul class=\"not-maddeler\">\n            <li>Tolerans, düzenli kullanımla vücudun kafeine alışması ve aynı etki için daha yüksek dozlara ihtiyaç duymasıdır.</li>\n            <li>14 gün boyunca kafein alımını keserek adenozin reseptörleri sıfırlanabilir.</li>\n            <li>Geçiş döneminde yeşil çay (L-theanine içerdiği için) yardımcı olabilir.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"accordion-item\">\n      <button class=\"accordion-header\">Vücudumda ne kadar süre etki eder?</button>\n      <div class=\"accordion-content\">\n        <div class=\"not-metin\">\n          <ul class=\"not-maddeler\">\n            <li>Kafein alımından sonra etkisi genellikle 30–60 dakika içinde başlar.</li>\n            <li>Uyanıklık, odaklanma ve performans etkisi 3–6 saat sürebilir.</li>\n            <li>Yarılanma ömrü ortalama 4–6 saattir; yani alınan dozun yarısı bu sürede vücuttan atılır.</li>\n            <li>Genetik, karaciğer enzim aktivitesi ve kullanılan ilaçlara göre bu süre kişiden kişiye değişebilir.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</div>\n\n    <div class=\"doz-bilgisi\">\n      <h6>Sporcularda Önerilen Üst Sınır:</h6>\n      <div class=\"not-metin\">\n        <strong>6 mg/kg</strong> genellikle egzersiz performansı için kullanılan <u>maksimum tek seferlik</u> dozdur. Kişinin kilosuna göre hesaplanır. Örneğin 70 kg biri için bu 420 mg’dır. Performans artışı sağlar ancak hassas kişilerde yan etki yapabilir.\n      </div>\n    </div>\n\n    <div class=\"doz-bilgisi\">\n      <h6>Resmi Kurumların Günlük Üst Sınırları:</h6>\n      <div class=\"not-metin\">\n        Günlük toplam kafein alımı sınırları kurumlara göre değişebilir. Aşağıdaki değerler <u>sabit mg cinsindendir</u>:\n        <ul class=\"not-maddeler\">\n          <li><strong>FDA (ABD):</strong> 400 mg/gün (sağlıklı yetişkinler)</li>\n          <li><strong>EFSA (AB):</strong> 400 mg/gün, tek seferde max 3 mg/kg</li>\n          <li><strong>WHO:</strong> Hamilelerde 300 mg/gün</li>\n          <li><strong>Türk Gıda Kodeksi:</strong> Takviyelerde 200 mg/gün</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım: 400 mg - 600 mg arası)</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Hafif sinirlilik, huzursuzluk, kaygı.</li>\n            <li>Uykusuzluk, uykuya dalmada zorluk.</li>\n            <li>Hafif kalp çarpıntısı, baş ağrısı.</li>\n            <li>Mide rahatsızlığı, mide bulantısı.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Çok yüksek odaklanma ve uyanıklık hali.</li>\n            <li>Egzersiz performansında ve güç çıktısında potansiyel olarak daha belirgin artış (toleransı yüksek bireylerde).</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (10 mg/kg üzeri)</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"kirmizi\"><strong>Potansiyel Riskler:</strong></span>\n          <ul>\n            <li>Bu dozlar, çoğu bireyde ciddi yan etkilere neden olabilir.</li>\n            <li>Vücut ağırlığına göre hesaplandığında yüksek kabul edilir.</li>\n          </ul>\n        </li>\n        <li><strong>1000 mg (1 gram) üzeri:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Şiddetli mide bulantısı, kusma, ishal.</li>\n                <li>Titreme, panik atak benzeri semptomlar.</li>\n                <li>Belirgin kalp çarpıntısı ve düzensiz kalp atışları (aritmi).</li>\n                <li>Tansiyonda ani yükseliş.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>5000 mg (5 gram) üzeri:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Aşırı şiddetli titreme, kas seğirmeleri.</li>\n                <li>Halüsinasyonlar, nöbetler, bilinç bulanıklığı.</li>\n                <li>Nefes darlığı, kalp krizi ve koma riski (hayati tehlike).</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n        <li><strong>10000 mg (10 gram) üzeri:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Akut kafein zehirlenmesi ve ölümcül sonuçlar.</li>\n                <li>Merkezi sinir sistemi ve kalp-damar sisteminde geri dönüşü olmayan hasar riski.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>DİKKAT:</h6>\n      <div class=\"not-metin kirmizi\">\n        <strong>Tıbbi uyarı:</strong><br>\n        Kalp-damar hastalığı, yüksek tansiyon, anksiyete bozukluğu veya uyku problemi olan bireylerde kafein kullanımı ciddi sağlık riski oluşturabilir. Yukarıda belirtilen <strong>1 gram ve üzeri dozlar</strong> tehlikeli kabul edilir ve acil tıbbi müdahale gerektirebilir.\n      </div>\n    </div>\n\n  </div>\n\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>\n", "karnitin": "<div id=\"karnitin\" class=\"section\">\n  <h3>L-Karnitin</h3>\n  <input type=\"number\" id=\"l_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaKarnitin()\" />\n  <span id=\"l_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaKarnitin()\">Hesapla</button>\n  <div id=\"karnitinSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">L-Karnitin Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Yağ asitlerini mitokondriye taşır. Eksikliği olan bireylerde enerji üretimini ve egzersiz kapasitesini destekleyebilir.\n        <br><strong>Nasıl kullanılır:</strong> Genellikle karbonhidrat içeren bir öğünle birlikte (emilimi artırmak için) veya antrenman öncesi alınır. Düzenli ve uzun süreli kullanım önemlidir.\n        <br><strong>Etki tipi ve süresi nedir:</strong> <span class=\"birikimli-vurgu\">Etkisi birikimlidir.</span> Etkileri hemen değil, uzun süreli ve düzenli kullanımda (haftalar/aylar) ortaya çıkar. Çoğu sağlıklı bireyde belirgin performans veya yağ yakımı etkisi görülmeyebilir.\n      </div>\n    </div>\n\n    <div class=\"faq-section\">\n      <h5 class=\"info-header\">Sıkça Sorulan Sorular:</h5>\n      <div class=\"accordion-container\">\n\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">L-Karnitin sağlığa zararlı mı?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Genel olarak güvenli kabul edilir, ancak yüksek dozlarda mide rahatsızlığı, ishal ve vücut kokusunda artış gibi yan etkiler görülebilir.</li>\n                <li>5 gram üzeri uzun süreli kullanımda olumsuz etkiler belirginleşebilir.</li>\n                <li>Herhangi bir takviyede olduğu gibi, sağlık profesyoneli onayıyla kullanılması önerilir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- Yeni Bölüm 1 -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">L-Karnitin gerçekten yağ yakar mı?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>L-Karnitin, yağ asitlerini mitokondrilere taşıyan bir moleküldür.</li>\n                <li>Sağlıklı bireylerde takviye alımı bu taşıma hızını artırmaz.</li>\n                <li>Bilimsel çalışmalar, doğrudan yağ yakımını artırmadığını göstermektedir.</li>\n                <li>Yağ yakımı için temel faktörler: kalori açığı, antrenman yoğunluğu ve metabolik adaptasyonlardır.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- Yeni Bölüm 2 -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">L-Karnitin kullanmak gerekli mi?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Sağlıklı ve aktif bireylerde, özellikle yeterli protein ve et tüketimi varsa, L-Karnitin takviyesi genellikle gereksizdir.</li>\n                <li>Takviye, şu gruplarda sınırlı fayda sağlayabilir:\n                  <ul>\n                    <li>Yaşlı bireyler (emilim ve sentez kapasitesi düşebilir)</li>\n                    <li>Vejetaryenler (diyetle yeterli karnitin alınmaz)</li>\n                    <li>Uzun süreli kardiyo yapan sporcular (dayanıklılık için destekleyici olabilir)</li>\n                    <li>Karnitin eksikliği tanısı almış bireyler (nadir metabolik bozukluklar)</li>\n                  </ul>\n                </li>\n                <li>Kullanım kararı kişiye özel olmalı, sağlık profesyoneliyle değerlendirilmelidir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">L-Karnitinin etkisi ne kadar sürer ve ne zaman biter?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>L-karnitinin etkisi, ihtiyacı olan bireylerde hemen başlamaz.</li>\n                <li>Kaslardaki karnitin seviyelerinin %10-20 artması için genellikle 3-4 hafta boyunca günlük 2-3 gram düzenli kullanım gerekir.</li>\n                <li>Takviye bırakıldığında ise, bu seviyeler yaklaşık 4-6 hafta içinde yavaşça normal haline döner.</li>\n                <li>Bu etkiler, özellikle vejetaryenler, veganlar veya karnitin eksikliği olan bireylerde daha belirgin olabilir. Sağlıklı ve dengeli beslenen genç bireylerde ise etki sınırlıdır.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Mide bulantısı, karın ağrısı, ishal, kusma (daha belirgin olabilir).</li>\n            <li>Vücut kokusunda artış (\"balık kokusu\" sendromu) riski.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Kas karnitin depolarının doygunluğa daha hızlı ulaşması potansiyeli.</li>\n            <li>Yoğun antrenman sonrası toparlanmada hafif bir iyileşme hissi (tartışmalı ve kişiye bağlı).</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 5 gram üzeri ve uzun süreli kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Şiddetli mide rahatsızlığı, bulantı, kusma, ishal.</li>\n                <li>Vücut kokusunda belirgin artış (\"balık kokusu\" sendromu).</li>\n                <li>Nadir durumlarda kas zayıflığı.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>", "kreatin": "<div id=\"kreatin\" class=\"section\">\n  <h3>Kreatin Monohidrat</h3>\n  <input type=\"number\" id=\"k_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatin()\" />\n  <span id=\"k_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaKreatin()\">Hesapla</button>\n  <div id=\"kreatinSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">Kreatin Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Kaslardaki fosfokreatin depolarını doldurarak patlayıcı güç ve kısa süreli performans artışı sağlar. Hücre içine su çekerek kasları daha dolgun gösterir ve bu hacim artışıyla birlikte kas kazanımını da destekler.\n        <br><strong>Nasıl kullanılır:</strong> Günlük idame dozu günün herhangi bir saati alınabilir. Yükleme evresi isteğe bağlıdır.\n        <br><strong>Etki tipi ve süresi nedir :</strong> <span class=\"birikimli-vurgu\">Etkisi birikimlidir.</span> Yükleme yapılırsa 5–7 gün içinde, yapılmazsa 3–4 hafta içinde hissedilmeye başlanır.\n\n      </div>\n    </div>\n\n    <div class=\"faq-section\">\n      <h5 class=\"info-header\">Sıkça Sorulan Sorular:</h5>\n      <div class=\"accordion-container\">\n\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Kreatin sağlığa zararlı mı?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Önerilen dozlarda (3–5 g/gün) kullanıldığında sağlıklı bireylerde güvenlidir.</li>\n                <li>Böbrek veya karaciğer üzerinde zararlı etkisi olduğuna dair bilimsel kanıt yoktur.</li>\n                <li>Mevcut böbrek hastalığı olanlar mutlaka doktora danışmalıdır.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Hangi kreatin formu en etkilidir?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Kreatin monohidrat, 30 yılı aşkın araştırmalarla kanıtlanmış en etkili ve güvenli formdur.</li>\n                <li>Piyasadaki diğer formlar (etil ester, HCl, buffered vb.) monohidrat kadar etkili değildir ve genellikle daha pahalıdır.</li>\n                <li>Saf kreatin monohidrat tercih edilmelidir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Saç döker mi?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Hayır, kreatin kullanımıyla saç dökülmesi arasında doğrudan bir bilimsel ilişki bulunmamaktadır. Bu, yaygın bir efsanedir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Kreatin kullanırken daha fazla su içmeli miyim?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Kreatin dehidrasyona neden olmaz ve ekstra su tüketimi zorunlu değildir.</li>\n                <li>Ancak, kaslarda su tutulumunu artırdığı için hidrasyonu desteklemek adına su alımını artırmak her zaman faydalıdır.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Nadir durumlarda mide rahatsızlığı, şişkinlik veya ishal.</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Kaslarda kreatin doygunluğuna daha hızlı ulaşım (yükleme evresi yapılıyorsa).</li>\n            <li>Bazı bireylerde potansiyel olarak daha hızlı güç artışı gözlemlenebilir.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek ve Uzun Süreli Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 30 gram üzeri ve uzun süreli kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Böbrekler üzerinde potansiyel ek yük (özellikle mevcut böbrek hastalığı olanlarda).</li>\n                <li>Mide-bağırsak rahatsızlıkları (şiddetli kramp, ishal, bulantı).</li>\n                <li>Dehidrasyon riski.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>DİKKAT:</h6>\n      <div class=\"not-metin kirmizi\">\n        <strong>Tıbbi uyarı:</strong><br>\n        Mevcut böbrek hastalığı olanlar kullanmadan önce mutlaka doktora danışmalıdır.\n      </div>\n    </div>\n\n  </div>\n\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>\n", "kreatinin": "<div id=\"kreatinin\" class=\"section\">\n    <h3>Kreatinin Tahmini</h3>\n    <div class=\"form-group\">\n      <label for=\"gender\">Cinsiyet</label>\n      <select id=\"gender\">\n        <option value=\"\">Seçiniz</option>\n        <option value=\"male\">Erkek</option>\n        <option value=\"female\">Kadın</option>\n      </select>\n      <span id=\"gender_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"age\">Yaş</label>\n      <input type=\"number\" id=\"age\" placeholder=\"Yaşınızı girin\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <span id=\"age_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"weight\">Kilo (kg)</label>\n      <input type=\"number\" id=\"weight\" placeholder=\"Kilonuzu girin\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <span id=\"weight_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"height\">Boy (cm)</label>\n      <input type=\"number\" id=\"height\" placeholder=\"Boyunuzu girin\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <span id=\"height_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"fat\">Yağ Oranı (%)</label>\n      <input type=\"number\" id=\"fat\" placeholder=\"Yağ oranınızı girin\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <p class=\"optional\">Opsiyonel</p>\n      <span id=\"fat_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"water\">Atılan Su (L)</label>\n      <input type=\"number\" id=\"water\" placeholder=\"Son 24 saatteki idrar hacmi\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <p class=\"optional\">Opsiyonel, ortalama 1.5</p>\n      <span id=\"water_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"protein\">Protein (g)</label>\n      <input type=\"number\" id=\"protein\" placeholder=\"Günlük etten alınan protein\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <p class=\"optional\">Opsiyonel, ortalama 60</p>\n      <span id=\"protein_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"creatine\">Kreatin (g)</label>\n      <input type=\"number\" id=\"creatine\" placeholder=\"Günlük kreatin takviyesi\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <p class=\"optional\">Opsiyonel, ortalama 0</p>\n      <span id=\"creatine_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"activity\">Aktivite (0-10)</label>\n      <input type=\"number\" id=\"activity\" placeholder=\"Ne kadar aktifsiniz? (10 en aktif)\" min=\"0\" max=\"10\" onkeyup=\"if(event.keyCode === 13) hesaplaKreatininTahmini()\">\n      <p class=\"optional\">Opsiyonel, ortalama 5</p>\n      <span id=\"activity_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <div class=\"form-group\">\n      <label for=\"lbmMethod\">LBM Hesaplama Yöntemi</label>\n      <select id=\"lbmMethod\">\n        <option value=\"fat\">Yağ Oranına Göre</option>\n        <option value=\"boer\">Boer Formülü (Boy ve Kilo)</option>\n        <option value=\"both\">Her İkisi</option>\n      </select>\n      <span id=\"lbmMethod_warning\" class=\"input-warning\"></span>\n    </div>\n\n    <button onclick=\"hesaplaKreatininTahmini()\">Hesapla</button>\n\n    <div class=\"result-card\" id=\"kreatininResultCard\" style=\"display:none\">\n      <div class=\"result-value\" id=\"kreatininResultValue\">0.00 - 0.00 mg/dL</div>\n      <div class=\"interpretation\" id=\"kreatininInterpretation\">Sonuçlarınız burada görünecek</div>\n    </div>\n\n    <div class=\"result-card\" id=\"kreatininResultFat\" style=\"display:none\">\n      <strong>Yağ oranına göre hesaplanan kreatinin:</strong>\n      <div class=\"result-value\" id=\"kreatininValueFat\">-</div>\n    </div>\n\n    <div class=\"result-card\" id=\"kreatininResultBoer\" style=\"display:none\">\n      <strong>Boer formülüne göre hesaplanan kreatinin:</strong>\n      <div class=\"result-value\" id=\"kreatininValueBoer\">-</div>\n    </div>\n\n    <div class=\"disclaimer danger\" style=\"margin-top: 20px; padding: 20px; background-color: #fef2f2; border: 2px solid #ef4444; border-radius: 8px;\">\n      <h5 style=\"color: #ef4444; font-weight: bold; font-size: 1.25rem; text-align: center;\">\n        <span style=\"font-size: 1.5em; vertical-align: middle;\">⚠️</span> ÖNEMLİ UYARI: BU BİR TIBBİ TAHMİN ARACIDIR!\n      </h5>\n      <p style=\"margin-top: 15px; font-weight: bold;\">\n        Bu hesaplayıcı, özellikle <strong><mark>ağır spor yapan ve kreatin takviyesi kullanan bireylerdeki yüksek kreatinin değerlerini</mark></strong> yorumlamaya yardımcı olmak için geliştirilmiştir.\n        Ancak, bilimsel bir temeli yoktur ve tamamen mantıksal tahminlere ve tecrübeye dayanır.\n      </p>\n      \n      <p style=\"font-weight: bold; color: #ef4444; margin: 15px 0; text-transform: uppercase;\">\n        ANCAK SAKIN UNUTMAYIN:\n      </p>\n      \n      <ul style=\"margin-bottom: 15px; padding-left: 25px;\">\n        <li style=\"color: #ef4444; font-weight: bold;\">Bu sonuçlar <mark style=\"text-decoration: underline; background-color: transparent;\">tıbbi değer taşımaz</mark> ve kesinlikle <mark style=\"text-decoration: underline; background-color: transparent;\">baz alınamaz</mark>.</li>\n        <li style=\"color: #ef4444;\">Sadece referans amaçlı kullanılabilir.</li>\n        <li style=\"color: #ef4444; font-weight: bold;\">Gerçek sağlık durumunuz için <mark style=\"text-decoration: underline; background-color: transparent;\">mutlaka bir doktora başvurmalısınız</mark>.</li>\n      </ul>\n      \n      <p style=\"font-size: 0.85rem; margin-top: 10px; text-align: center;\">\n        Bu araç, tıbbi teşhis veya tedavi amaçlı kullanılamaz.\n      </p>\n    </div>\n    \n    <div class=\"disclaimer\" style=\"margin-top: 20px; padding: 15px; background-color: #f0f9ff; border: 1px solid #93c5fd; border-radius: 8px;\">\n      <p><strong>Uyarı:</strong> Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.</p>\n    </div>\n</div>\n", "protein": "<div id=\"protein\" class=\"section\">\n  <h3>Günlük Protein İhtiyacı</h3>\n  <input type=\"number\" id=\"p_kilo\" placeholder=\"Kilonuz (kg)\">\n  <span id=\"p_kilo_warning\" class=\"input-warning\"></span>\n\n  <div class=\"accordion-container calculator-accordion hedef-accordion\" data-hedef-target=\"p_hedef\">\n    <div class=\"accordion-item\">\n      <button type=\"button\" class=\"accordion-header\">Hedefini seç</button>\n      <div class=\"accordion-content\">\n        <div class=\"hedef-options\">\n          <button type=\"button\" class=\"hedef-option\" data-value=\"koruma\">Kilo Korumak (Maintenance)</button>\n          <button type=\"button\" class=\"hedef-option\" data-value=\"alma\">Kilo Almak (Bulk)</button>\n          <button type=\"button\" class=\"hedef-option\" data-value=\"verme\">Kilo Vermek (Definasyon)</button>\n        </div>\n        <select id=\"p_hedef\" class=\"hedef-select-hidden\">\n          <option value=\"\">-- Hedefinizi Seçiniz --</option>\n          <option value=\"koruma\">Kilo Korumak (Maintenance)</option>\n          <option value=\"alma\">Kilo Almak (Bulk)</option>\n          <option value=\"verme\">Kilo Vermek (Definasyon)</option>\n        </select>\n        <span id=\"p_hedef_warning\" class=\"input-warning\"></span>\n      </div>\n    </div>\n  </div>\n\n  <button onclick=\"hesaplaProtein()\">Hesapla</button>\n  <div id=\"proteinSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <div class=\"info-section\">\n      <h5>Protein Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Kas onarımı ve büyümesi için temel yapı taşıdır. Tokluk hissini artırır, metabolizmayı hızlandırır.\n        <br><strong>Nasıl kullanılır:</strong> Günlük ihtiyacı karşılamak üzere ana öğünlere ve ara öğünlere yayılarak alınır. Protein tozları pratik bir ek olabilir.\n        <br><strong>Etki tipi ve süresi nedir :</strong> <span class=\"uzun-vade-vurgu\">Etkisi uzun vadelidir.</span> Düzenli ve yeterli alımda kas gelişimi ve toparlanması üzerinde etki gösterir ve akut olarak tokluk hissi sağlar.\n      </div>\n    </div>\n\n    <div class=\"faq-section\">\n      <h5>Sıkça Sorulan Sorular:</h5>\n      <div class=\"accordion-container\">\n\n        <div class=\"accordion-item\">\n  <button class=\"accordion-header\">Fazla protein zararlı mı?</button>\n  <div class=\"accordion-content\">\n    <div class=\"not-metin\">\n      <ul>\n        <li>Sağlıklı bireylerde günlük 2.0–2.4 g/kg seviyesine kadar protein alımı genellikle güvenlidir.</li>\n        <li>Uzun süreli ve aşırı alım (>3 g/kg/gün), özellikle sıvı alımı yetersizse böbrekler üzerinde ek yük oluşturabilir.</li>\n        <li>Mevcut böbrek hastalığı olan bireylerde protein kısıtlaması gerekebilir; mutlaka doktora danışılmalıdır.</li>\n        <li>Karaciğer fonksiyonları normal olan bireylerde doğrudan toksik etki bildirilmemiştir.</li>\n        <li>Sindirim sisteminde şişkinlik, gaz, ishal gibi yan etkiler görülebilir; özellikle düşük kaliteli protein kaynaklarında.</li>\n      </ul>\n    </div>\n  </div>\n</div>\n\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Bitkisel protein tozları (bezelye, pirinç) hayvansal protein kadar etkili mi?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Bezelye proteini (lisin açısından zengin) ve pirinç proteini (metiyonin açısından zengin) 70:30 oranında karıştırılırsa, whey proteine yakın amino asit profili sağlar.</li>\n                <li>Veganlar için BCAA eklenmesi önerilir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Hafif şişkinlik, gaz.</li>\n            <li>Enerji dengesinde hafif kaymalar (karbonhidrat ve yağ alımı azaldığında).</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Belirli durumlarda tokluk hissini artırabilir, bu da kilo kontrolüne yardımcı olabilir.</li>\n            <li>Yoğun antrenman dönemlerinde kas yıkımını minimize etmeye yardımcı olabilir.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n <div class=\"doz-bilgisi danger\">\n  <h6>Aşırı Doz Aşımı (Çok Yüksek ve Uzun Süreli Alım):</h6>\n  <ul class=\"not-maddeler\">\n    <li><strong>Günlük 3.5 gr/kg üzeri ve uzun süreli kullanım:</strong>\n      <ul>\n        <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n          <ul>\n            <li>Mide rahatsızlığı, bulantı, ishal.</li>\n            <li>Uzun süreli aşırı alım böbrekler üzerinde ek yük oluşturabilir (özellikle mevcut böbrek hastalığı olanlar için).</li>\n            <li>Vücutta sıvı dengesizliği.</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Tek seferde 0.8 gr/kg üzeri alım:</strong>\n      <ul>\n        <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n          <ul>\n            <li>Akut mide bulantısı, şişkinlik ve geçici ishal.</li>\n            <li>Osmotik yük nedeniyle bağırsaklarda sıvı çekilmesi.</li>\n            <li>Hızlı alım sonrası geçici elektrolit dengesizliği.</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n  </ul>\n</div>\n\n  </div>\n\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>\n", "sitrulin": "<div id=\"sitrulin\" class=\"section\">\n  <h3>Sitrülin Malat</h3>\n  <input type=\"number\" id=\"s_kilo\" placeholder=\"Kilonuz (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaSitrulin()\" />\n  <span id=\"s_kilo_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaSitrulin()\">Hesapla</button>\n  <div id=\"sitrulinSonuc\" class=\"result\"></div>\n\n  <div class=\"supplement-section-info\">\n\n    <!-- Bilgilendirme -->\n    <div class=\"info-section\">\n      <h5 class=\"info-header\">Sitrülin Malat Hakkında Bilgi:</h5>\n      <div class=\"not-metin\">\n        <strong>Ne işe yarar:</strong> Vücutta nitrik oksit (NO) üretimini destekler, kan akışını iyileştirir, antrenman sırasında \"pump\" hissini artırır, kaslara besin ve oksijen iletimini destekler ve yorgunluğu geciktirir.\n        <br><strong>Nasıl kullanılır:</strong> Genellikle antrenmandan 30–60 dakika önce alınır. Dinlenme günlerinde alınması zorunlu değildir ancak genel dolaşım sağlığı ve toparlanma için saf L-Sitrülin (yaklaşık 1–3 gram) düşünülebilir.\n        <br><strong>Etki tipi ve süresi nedir:</strong> <span class=\"akut-vurgu\">Etkisi akuttur.</span> İlk kullanımdan itibaren 30–60 dakika içinde etkileri (pump, dayanıklılık) hissedilebilir. Düzenli kullanımda daha belirginleşir.\n      </div>\n    </div>\n\n    <!-- SSS -->\n    <div class=\"faq-section\">\n      <h5 class=\"info-header\">Sıkça Sorulan Sorular:</h5>\n      <div class=\"accordion-container\">\n\n        <!-- 1. Sağlığa zararlı mı? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Sitrülin Malat sağlığa zararlı mı?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Önerilen dozlarda alındığında genellikle güvenlidir.</li>\n                <li>Yüksek dozlarda mide rahatsızlığı, bulantı ve tansiyon düşüklüğü görülebilir.</li>\n                <li>Tansiyon ilacı kullananlar veya hipotansiyonu olanlar dikkatli olmalıdır.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. Kan basıncına etkisi -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Sitrülin'in kan basıncına etkisi nedir?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Sitrülin, damarları genişleten nitrik oksit (NO) üretimini artırır. Bu etki, kan akışını iyileştirirken kan basıncını hafifçe düşürebilir.</li>\n                <li>Tansiyon ilacı kullanan veya düşük tansiyonu olan kişilerin dikkat etmesi önemlidir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. Sitrülin Malat vs Saf L-Sitrülin -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Sitrülin Malat ile Saf L-Sitrülin farkı nedir?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Sitrülin Malat, Sitrülin amino asidi ve enerji döngüsüne (Krebs döngüsü) katılan <strong>Malik Asit</strong>in birleşimidir. Bu sayede Sitrülin Malat, hem \"pump\" hissini hem de enerji üretimini destekleyerek performansı artırır.</li>\n                <li>Saf L-Sitrülin ise daha çok dolaşım sağlığına odaklanır.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4. Mide bulantısı -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Mide bulantısı normal mi?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Evet, yüksek dozda alımlarda hafif mide rahatsızlığı veya bulantı görülebilir. Bu normal bir yan etkidir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 5. Tadı neden ekşi? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Tadı neden ekşi?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Sitrülin Malat, içeriğindeki malik asit nedeniyle doğal olarak ekşi bir tada sahiptir. Bu, ürünün bozuk olduğu anlamına gelmez.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n        <!-- 6. Dinlenme günlerinde alınmalı mı? -->\n        <div class=\"accordion-item\">\n          <button class=\"accordion-header\">Dinlenme günlerinde de alınmalı mı?</button>\n          <div class=\"accordion-content\">\n            <div class=\"not-metin\">\n              <ul>\n                <li>Performans artışı için sadece antrenman günleri yeterlidir.</li>\n                <li>Ancak genel dolaşım sağlığı için saf L-Sitrülin formunun (yaklaşık 1–3 gram) dinlenme günlerinde de alınması faydalı olabilir.</li>\n              </ul>\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <!-- Doz Bilgisi -->\n    <div class=\"doz-bilgisi\">\n      <h6>Doz Aşımı (Hafifçe Yüksek Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><span class=\"turuncu\">Olası Olumsuz Etkileri:</span>\n          <ul>\n            <li>Mide rahatsızlığı, hafif bulantı veya ishal (özellikle yüksek dozlarda).</li>\n            <li>Tansiyonda hafif düşüş (özellikle hassas kişilerde).</li>\n          </ul>\n        </li>\n        <li><span class=\"yesil\">Olası Olumlu Etkileri:</span>\n          <ul>\n            <li>Daha yoğun \"pump\" hissi ve kan akışında potansiyel olarak ek iyileşme .</li>\n            <li>Fazladan ATP(enerji).</li>\n            <li>Yorgunluğun daha belirgin bir şekilde gecikmesi.</li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>Aşırı Doz Aşımı (Çok Yüksek ve Uzun Süreli Alım):</h6>\n      <ul class=\"not-maddeler\">\n        <li><strong>Günlük 20 gram üzeri ve uzun süreli kullanım:</strong>\n          <ul>\n            <li><span class=\"kirmizi\">Olumsuz Etkileri:</span>\n              <ul>\n                <li>Şiddetli mide rahatsızlığı, bulantı, kusma, ishal.</li>\n                <li>Belirgin tansiyon düşüşü (hipotansiyon) ve buna bağlı baş dönmesi, bayılma.</li>\n                <li>Elektrolit dengesizlikleri.</li>\n              </ul>\n            </li>\n          </ul>\n        </li>\n      </ul>\n    </div>\n\n    <div class=\"doz-bilgisi danger\">\n      <h6>DİKKAT:</h6>\n      <div class=\"not-metin kirmizi\">\n        <strong>Tıbbi uyarı:</strong>\n        <ul style=\"margin-top: 5px; padding-left: 20px;\">\n          <li>Tansiyon ilacı kullananlar ve düşük tansiyon problemi olanlar dikkatli olmalıdır, kan basıncını düşürebilir.</li>\n          <li>Nitrik oksit takviyeleri ile birlikte kullanılacaksa dikkatli olunmalıdır.</li>\n        </ul>\n      </div>\n    </div>\n\n  </div>\n\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber", "yag": "<div id=\"yag\" class=\"section\">\n  <h3>Yağ Oranı & Vücut Kitle İndeksi (VKİ)</h3>\n  <select id=\"y_cinsiyet\" onchange=\"toggleHipInput()\">\n    <option value=\"\">-- Cinsiyetinizi Seçiniz --</option>\n    <option value=\"erkek\">Erkek</option>\n    <option value=\"kadin\">Kadın</option>\n  </select>\n  <span id=\"y_cinsiyet_warning\" class=\"input-warning\"></span>\n  <input type=\"number\" id=\"y_boy\" placeholder=\"Boy (cm)\" onkeyup=\"if(event.keyCode === 13) hesaplaYagOrani()\" />\n  <span id=\"y_boy_warning\" class=\"input-warning\"></span>\n  <input type=\"number\" id=\"y_kilo\" placeholder=\"Kilo (kg)\" onkeyup=\"if(event.keyCode === 13) hesaplaYagOrani()\" />\n  <span id=\"y_kilo_warning\" class=\"input-warning\"></span>\n  <input type=\"number\" id=\"y_boyun\" placeholder=\"Boyun Çevresi (cm)\" onkeyup=\"if(event.keyCode === 13) hesaplaYagOrani()\" />\n  <span id=\"y_boyun_warning\" class=\"input-warning\"></span>\n  <input type=\"number\" id=\"y_bel\" placeholder=\"Bel Çevresi (cm)\" onkeyup=\"if(event.keyCode === 13) hesaplaYagOrani()\" />\n  <span id=\"y_bel_warning\" class=\"input-warning\"></span>\n  <input type=\"number\" id=\"y_kalca\" placeholder=\"Kalça Çevresi (cm)\" class=\"hidden\" onkeyup=\"if(event.keyCode === 13) hesaplaYagOrani()\" />\n  <span id=\"y_kalca_warning\" class=\"input-warning\"></span>\n  <button onclick=\"hesaplaYagOrani()\">Hesapla</button>\n  <div id=\"yagSonuc\" class=\"result\"></div>\n  <div id=\"vkiSonuc\" class=\"result\"></div>\n\n  <h4>Vücut Yağ Oranı Kategorileri (Genel Rehber)</h4>\n  <table>\n    <thead>\n      <tr>\n        <th>Kategori</th>\n        <th>Erkekler (%)</th>\n        <th>Kadınlar (%)</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>Temel Yağ</td>\n        <td>2-5%</td>\n        <td>10-13%</td>\n      </tr>\n      <tr>\n        <td>Atletik</td>\n        <td>6-13%</td>\n        <td>14-20%</td>\n      </tr>\n      <tr>\n        <td>Fit</td>\n        <td>14-17%</td>\n        <td>21-24%</td>\n      </tr>\n      <tr>\n        <td>Ortalama</td>\n        <td>18-24%</td>\n        <td>25-31%</td>\n      </tr>\n      <tr>\n        <td>Obez</td>\n        <td>25%+</td>\n        <td>32%+</td>\n      </tr>\n    </tbody>\n  </table>\n\n  <h4>Vücut Kitle İndeksi (VKİ) Kategorileri</h4>\n  <table>\n    <thead>\n      <tr>\n        <th>VKİ</th>\n        <th>Kategori</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>&lt; 18.5</td>\n        <td>Zayıf</td>\n      </tr>\n      <tr>\n        <td>18.5 - 24.9</td>\n        <td>Normal Kilolu</td>\n      </tr>\n      <tr>\n        <td>25.0 - 29.9</td>\n        <td>Fazla Kilolu</td>\n      </tr>\n      <tr>\n        <td>30.0 - 34.9</td>\n        <td>Obezite (1. Derece)</td>\n      </tr>\n      <tr>\n        <td>35.0 - 39.9</td>\n        <td>Obezite (2. Derece)</td>\n      </tr>\n      <tr>\n        <td>&gt;= 40.0</td>\n        <td>Morbid Obezite (3. Derece)</td>\n      </tr>\n    </tbody>\n  </table>\n  <div class=\"disclaimer\">\n    Uyarı: Bu hesaplayıcıdaki bilgiler genel rehber niteliğindedir ve tıbbi tavsiye yerine geçmez. Sağlık durumunuz veya supplement kullanımı hakkında karar vermeden önce daima bir sağlık profesyoneline danışın.\n  </div>\n</div>"};
